// Consolida as quatro respostas do CRM sem confundir campos de negocio com o envelope HTTP.
// Importante: mensagem festiva possui um campo chamado data. Ele NAO e o body da resposta.

function respostaDo(nome) {
  const itens = $(nome).all().map((item) => item.json ?? {});
  if (itens.length === 0) return { statusCode: 204, body: null };

  const primeira = itens[0];
  const temEnvelopeHttp = Object.prototype.hasOwnProperty.call(primeira, 'body');
  return {
    statusCode: Number(temEnvelopeHttp ? (primeira.statusCode ?? 200) : 200),
    body: temEnvelopeHttp ? primeira.body : (itens.length === 1 ? primeira : itens),
  };
}

function lista(valor) {
  if (Array.isArray(valor)) return valor;
  if (Array.isArray(valor?.items)) return valor.items;
  if (Array.isArray(valor?.data)) return valor.data;
  if (Array.isArray(valor?.resultados)) return valor.resultados;
  if (Array.isArray(valor?.leads)) return valor.leads;
  return [];
}

function parametro(fonte, chave) {
  const itens = fonte?.parametros ?? fonte?.items ?? fonte?.data ?? fonte;
  if (Array.isArray(itens)) {
    const item = itens.find((x) => String(x.chave ?? x.key ?? '') === chave);
    return item?.valor ?? item?.value;
  }
  return itens?.[chave];
}

const geral = respostaDo('Buscar configurações gerais');
const aniversariantes = respostaDo('Buscar aniversariantes de hoje');
const festivas = respostaDo('Buscar mensagem festiva de hoje');
const regras = respostaDo('Buscar regras de fidelização');

// Festivas sem cadastro hoje podem chegar como lista vazia (200) ou 404, conforme a versao do CRM.
const falhas = [
  ['configuracoes gerais', geral, false],
  ['aniversariantes de hoje', aniversariantes, false],
  ['mensagens festivas de hoje', festivas, true],
  ['regras de fidelizacao', regras, false],
].filter(([, resposta, permite404]) =>
  (resposta.statusCode < 200 || resposta.statusCode >= 300) && !(permite404 && resposta.statusCode === 404),
).map(([nome, resposta]) => ({ nome, statusCode: resposta.statusCode }));

const corpoAniversario = aniversariantes.body ?? {};
const leadsAniversariantes = lista(corpoAniversario.leads ?? corpoAniversario);
const habilitadoNoEndpoint = typeof corpoAniversario.habilitado === 'boolean'
  ? corpoAniversario.habilitado
  : null;
const habilitadoNaConfig = String(parametro(geral.body, 'fidelizacao.aniversario.habilitado')).toLowerCase() === 'true';
const mensagemAniversario = corpoAniversario.mensagem
  ?? parametro(geral.body, 'fidelizacao.aniversario.mensagem')
  ?? null;

let mensagensFestivas = [];
if (festivas.statusCode >= 200 && festivas.statusCode < 300) {
  mensagensFestivas = lista(festivas.body);
  // Compatibilidade com a resposta antiga que devolvia um objeto unico.
  if (mensagensFestivas.length === 0 && festivas.body?.mensagem) mensagensFestivas = [festivas.body];
}

const regrasAtivas = lista(regras.body)
  .filter((regra) => regra.ativo !== false && regra.habilitado !== false)
  .filter((regra) => Number(regra.diasSemContato ?? regra.dias_sem_contato) > 0 && String(regra.mensagem ?? '').trim());

return [{ json: {
  configuracoesDisponiveis: falhas.length === 0,
  falhasDeConsulta: falhas,
  aniversario: {
    habilitado: habilitadoNoEndpoint ?? habilitadoNaConfig,
    mensagem: mensagemAniversario,
    aniversariantesHoje: leadsAniversariantes,
  },
  festiva: {
    mensagensConfiguradasHoje: mensagensFestivas,
    elegivelParaDisparo: mensagensFestivas.length > 0,
  },
  regrasFidelizacaoAtivas: regrasAtivas,
  totalAniversariantesHoje: leadsAniversariantes.length,
  totalMensagensFestivasHoje: mensagensFestivas.length,
  totalRegrasFidelizacaoAtivas: regrasAtivas.length,
} }];

// Diagnóstico da saída falsa: os status HTTP ficam explícitos na execução.
const resultado = $("Consolidar configurações remotas").first().json;
return [{ json: {
  status: "CONFIGURACAO_REMOTA_INDISPONIVEL",
  falhasDeConsulta: resultado.falhasDeConsulta,
  acao: "Corrigir a rota ou autorização da credencial CRM Synapse Interno.",
} }];

// Monta um item por destinatário para a categoria ANIVERSARIO.
// O texto vem do CRM e entra como o único parâmetro BODY do template Meta.
// Sem template aprovado, texto ou telefone, não devolvemos item e não enviamos nada.

const dados = $("Consolidar configurações remotas").first().json;
const meta = $("Configurar template Meta marketing").first().json;
const templateNome = String(meta.template_nome_marketing ?? "").trim();
const templateIdioma = String(meta.template_idioma ?? "pt_BR").trim();
const phoneNumberId = String(meta.phone_number_id_meta ?? "").trim();

function lista(valor) {
  return Array.isArray(valor) ? valor : valor?.items ?? valor?.data ?? valor?.resultados ?? [];
}

function telefoneDo(destinatario) {
  return String(
    destinatario.telefoneNormalizado ??
    destinatario.telefone_normalizado ??
    destinatario.telefone ??
    destinatario.waId ??
    destinatario.wa_id ??
    destinatario.phone ??
    ""
  ).replace(/\D/g, "");
}

const candidatos = dados.aniversario.aniversariantesHoje;
const textoConfigurado = String(dados.aniversario.mensagem ?? "").trim();

if (!templateNome || !templateIdioma || !phoneNumberId || !textoConfigurado) {
  return [];
}

return lista(candidatos)
  .map((destinatario) => {
    const telefone = telefoneDo(destinatario);
    const nome = String(destinatario.nome ?? destinatario.leadNome ?? "").trim();
    const leadId = String(destinatario.leadId ?? destinatario.lead_id ?? destinatario.id ?? "").trim();
    const textoParaTemplate = textoConfigurado
      .replace(/\[nome\]/gi, nome)
      .replace(/\s{2,}/g, " ")
      .trim();

    if (!leadId || !telefone || !textoParaTemplate) return null;

    return {
      json: {
        categoria: "ANIVERSARIO",
        template_id_referencia: String(meta.template_id_meta ?? ""),
        lead_id: leadId,
        telefone,
        phone_number_id: phoneNumberId,
        nome_recebido: nome,
        texto_original: textoConfigurado,
        texto_configurado: textoParaTemplate,
        payload_meta: {
          messaging_product: "whatsapp",
          recipient_type: "individual",
          to: telefone,
          type: "template",
          template: {
            name: templateNome,
            language: { code: templateIdioma },
            components: [{
              type: "body",
              parameters: [{ type: "text", parameter_name: "texto", text: textoParaTemplate }],
            }],
          },
        },
      },
    };
  })
  .filter(Boolean);

// A lista de aniversariantes vem do endpoint interno do CRM.

// Cruza as mensagens festivas de hoje com as paginas de leads devolvidas pelo CRM.
// Cada combinacao mensagem + lead recebe uma chave diaria e passa pela reserva anti-repeticao.

const dados = $('Consolidar configurações remotas').first().json;
const meta = $('Configurar template Meta marketing').first().json;
const configuracao = $('Bases do CRM').first().json;
const mensagens = dados.festiva.mensagensConfiguradasHoje ?? [];
const templateNome = String(meta.template_nome_marketing ?? '').trim();
const templateIdioma = String(meta.template_idioma ?? 'pt_BR').trim();
const phoneNumberId = String(meta.phone_number_id_meta ?? '').trim();

function normalizarTelefone(valor) {
  let telefone = String(valor ?? '').replace(/\D/g, '');
  if (telefone.startsWith('55') && (telefone.length === 12 || telefone.length === 13)) telefone = telefone.slice(2);
  return telefone;
}

function leadsDaResposta(valor) {
  if (Array.isArray(valor)) return valor.flatMap(leadsDaResposta);
  if (Array.isArray(valor?.leads)) return valor.leads;
  if (valor?.body) return leadsDaResposta(valor.body);
  if (valor?.id && valor?.telefone) return [valor];
  return [];
}

function dataHojeNoFuso() {
  const partes = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/Sao_Paulo', year: 'numeric', month: '2-digit', day: '2-digit',
  }).formatToParts(new Date()).reduce((acc, parte) => ({ ...acc, [parte.type]: parte.value }), {});
  return partes.year + '-' + partes.month + '-' + partes.day;
}

const telefoneTeste = normalizarTelefone(configuracao.telefone_teste);
const modoTeste = configuracao.modo_teste === true;
const unicos = new Map();
for (const item of $input.all()) {
  for (const lead of leadsDaResposta(item.json)) unicos.set(String(lead.id ?? lead.leadId), lead);
}

if (!templateNome || !templateIdioma || !phoneNumberId) return [];
const ciclo = dataHojeNoFuso();
const saida = [];

for (const mensagem of mensagens) {
  const textoOriginal = String(mensagem.mensagem ?? mensagem.texto ?? '').trim();
  if (!textoOriginal) continue;
  const referencia = String(mensagem.id ?? (mensagem.titulo ?? 'FESTIVA') + '-' + String(mensagem.data ?? ciclo));

  for (const lead of unicos.values()) {
    const leadId = String(lead.id ?? lead.leadId ?? '').trim();
    const nome = String(lead.nome ?? lead.leadNome ?? '').trim();
    const telefone = String(lead.telefone ?? lead.telefoneNormalizado ?? '').replace(/\D/g, '');
    if (!leadId || !telefone) continue;
    if (modoTeste && (!telefoneTeste || normalizarTelefone(telefone) !== telefoneTeste)) continue;
    if (/(\[nome\]|\{nome\})/i.test(textoOriginal) && !nome) continue;

    const texto = textoOriginal.replace(/\[nome\]|\{nome\}/gi, nome).replace(/\s{2,}/g, ' ').trim();
    const payload = {
      messaging_product: 'whatsapp', recipient_type: 'individual', to: telefone, type: 'template',
      template: {
        name: templateNome, language: { code: templateIdioma },
        components: [{ type: 'body', parameters: [{ type: 'text', parameter_name: 'texto', text: texto }] }],
      },
    };

    saida.push({ json: {
      categoria: 'DATA_FESTIVA', referencia_id: referencia, ciclo_chave: ciclo,
      lead_id: leadId, telefone, nome_lead: nome, phone_number_id: phoneNumberId,
      texto_original: textoOriginal, texto_configurado: texto,
      texto_base64: Buffer.from(texto, 'utf8').toString('base64'),
      payload_meta: payload,
      payload_base64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    } });
  }
}

return saida;

// Seleciona, para cada lead inativo, somente a maior regra de fidelizacao que ele ja atingiu.
// Isso evita mandar de uma vez as mensagens de 30, 60 e 90 dias para o mesmo lead antigo.

const dados = $('Consolidar configurações remotas').first().json;
const meta = $('Configurar template Meta marketing').first().json;
const configuracao = $('Bases do CRM').first().json;
const templateNome = String(meta.template_nome_marketing ?? '').trim();
const templateIdioma = String(meta.template_idioma ?? 'pt_BR').trim();
const phoneNumberId = String(meta.phone_number_id_meta ?? '').trim();
const regras = (dados.regrasFidelizacaoAtivas ?? [])
  .map((regra) => ({ ...regra, dias: Number(regra.diasSemContato ?? regra.dias_sem_contato) }))
  .filter((regra) => Number.isFinite(regra.dias) && regra.dias > 0 && String(regra.mensagem ?? '').trim())
  .sort((a, b) => a.dias - b.dias);

function normalizarTelefone(valor) {
  let telefone = String(valor ?? '').replace(/\D/g, '');
  if (telefone.startsWith('55') && (telefone.length === 12 || telefone.length === 13)) telefone = telefone.slice(2);
  return telefone;
}

function leadsDaResposta(valor) {
  if (Array.isArray(valor)) return valor.flatMap(leadsDaResposta);
  if (Array.isArray(valor?.leads)) return valor.leads;
  if (valor?.body) return leadsDaResposta(valor.body);
  if (valor?.id && valor?.telefone) return [valor];
  return [];
}

const telefoneTeste = normalizarTelefone(configuracao.telefone_teste);
const modoTeste = configuracao.modo_teste === true;
const agora = Date.now();
const unicos = new Map();
for (const item of $input.all()) {
  for (const lead of leadsDaResposta(item.json)) unicos.set(String(lead.id ?? lead.leadId), lead);
}

if (!templateNome || !templateIdioma || !phoneNumberId || regras.length === 0) return [];
const saida = [];

for (const lead of unicos.values()) {
  const leadId = String(lead.id ?? lead.leadId ?? '').trim();
  const nome = String(lead.nome ?? lead.leadNome ?? '').trim();
  const telefone = String(lead.telefone ?? lead.telefoneNormalizado ?? '').replace(/\D/g, '');
  const marco = String(lead.ultimaInteracaoEm ?? lead.ultima_interacao_em ?? lead.criadoEm ?? lead.criado_em ?? '').trim();
  const marcoMs = Date.parse(marco);
  if (!leadId || !telefone || !Number.isFinite(marcoMs)) continue;
  if (modoTeste && (!telefoneTeste || normalizarTelefone(telefone) !== telefoneTeste)) continue;

  const diasSemContato = Math.floor((agora - marcoMs) / 86400000);
  const regra = regras.filter((item) => item.dias <= diasSemContato).at(-1);
  if (!regra) continue;

  const textoOriginal = String(regra.mensagem).trim();
  if (/(\[nome\]|\{nome\})/i.test(textoOriginal) && !nome) continue;
  const texto = textoOriginal.replace(/\[nome\]|\{nome\}/gi, nome).replace(/\s{2,}/g, ' ').trim();
  const payload = {
    messaging_product: 'whatsapp', recipient_type: 'individual', to: telefone, type: 'template',
    template: {
      name: templateNome, language: { code: templateIdioma },
      components: [{ type: 'body', parameters: [{ type: 'text', parameter_name: 'texto', text: texto }] }],
    },
  };

  saida.push({ json: {
    categoria: 'FIDELIZACAO',
    referencia_id: String(regra.id ?? 'DIAS-' + regra.dias),
    regra_id: String(regra.id ?? ''), regra_dias_sem_contato: regra.dias,
    ciclo_chave: marco,
    lead_id: leadId, telefone, nome_lead: nome, phone_number_id: phoneNumberId,
    dias_sem_contato_calculados: diasSemContato,
    texto_original: textoOriginal, texto_configurado: texto,
    texto_base64: Buffer.from(texto, 'utf8').toString('base64'),
    payload_meta: payload,
    payload_base64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
  } });
}

return saida;

// Combina o aniversariante do endpoint interno com a ficha atual do lead.
// Resolve [nome] ou {nome}, repete a trava de teste e gera a chave anual de idempotencia.

const preparados = $('Preparar envios aniversário').all();
const configuracao = $('Bases do CRM').first().json;
const modoTeste = configuracao.modo_teste === true;
const telefoneTeste = normalizarTelefone(configuracao.telefone_teste);

function normalizarTelefone(valor) {
  let telefone = String(valor ?? '').replace(/\D/g, '');
  if (telefone.startsWith('55') && (telefone.length === 12 || telefone.length === 13)) telefone = telefone.slice(2);
  return telefone;
}

function anoNoFuso() {
  return new Intl.DateTimeFormat('en-US', { timeZone: 'America/Sao_Paulo', year: 'numeric' }).format(new Date());
}

return $input.all().map((resposta, index) => {
  const envio = preparados[index]?.json ?? {};
  const bruto = resposta.json ?? {};
  const lead = bruto.data && !Array.isArray(bruto.data) ? bruto.data : bruto;
  const nome = String(lead.nome ?? lead.nomeCompleto ?? lead.nome_completo ?? lead.name ?? envio.nome_recebido ?? '').trim();
  const telefone = String(lead.telefoneNormalizado ?? lead.telefone_normalizado ?? lead.telefone ?? lead.whatsapp ?? envio.telefone ?? '').replace(/\D/g, '');
  const textoOriginal = String(envio.texto_original ?? envio.texto_configurado ?? '').trim();

  if (/(\[nome\]|\{nome\})/i.test(textoOriginal) && !nome) return null;
  const texto = textoOriginal.replace(/\[nome\]|\{nome\}/gi, nome).replace(/\s{2,}/g, ' ').trim();
  if (!telefone || !texto || !envio.lead_id) return null;
  if (modoTeste && (!telefoneTeste || normalizarTelefone(telefone) !== telefoneTeste)) return null;

  const payload = JSON.parse(JSON.stringify(envio.payload_meta ?? {}));
  payload.to = telefone;
  payload.template.components[0].parameters[0] = { type: 'text', parameter_name: 'texto', text: texto };

  return { json: {
    ...envio,
    referencia_id: 'ANIVERSARIO',
    ciclo_chave: anoNoFuso(),
    nome_lead: nome,
    telefone,
    texto_configurado: texto,
    texto_base64: Buffer.from(texto, 'utf8').toString('base64'),
    payload_meta: payload,
    payload_base64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
  }, pairedItem: { item: index } };
}).filter(Boolean);

// Cria uma unica consulta paginada para o publico da data festiva.
// O endpoint festivo decide o conteudo/data; o filtro de leads decide os destinatarios.

const dados = $('Consolidar configurações remotas').first().json;
const configuracao = $('Bases do CRM').first().json;
const mensagens = dados.festiva.mensagensConfiguradasHoje ?? [];
if (!Array.isArray(mensagens) || mensagens.length === 0) return [];

const todosOsStatus = { tipo: 'SIMPLES', campo: 'status', operador: 'EM', valores: ['IA', 'EM_ATENDIMENTO', 'FINALIZADO'] };
let criterio = todosOsStatus;

if (configuracao.modo_teste === true) {
  const telefone = String(configuracao.telefone_teste ?? '').replace(/\D/g, '');
  if (!telefone) return [];
  const telefoneLocal = telefone.startsWith('55') ? telefone.slice(2) : telefone;
  criterio = {
    tipo: 'COMPOSTO', conector: 'E', criterios: [
      todosOsStatus,
      { tipo: 'SIMPLES', campo: 'telefone', operador: 'CONTEM', valor: telefoneLocal },
    ],
  };
}

return [{ json: { filtro: { criterio, pagina: 0, tamanho: 200 } } }];

// Busca candidatos uma unica vez usando a menor regra ativa.
// Depois do retorno, o node Preparar envios fidelizacao escolhe a maior regra ja atingida por cada lead.

const dados = $('Consolidar configurações remotas').first().json;
const configuracao = $('Bases do CRM').first().json;
const regras = (dados.regrasFidelizacaoAtivas ?? [])
  .map((regra) => ({ ...regra, dias: Number(regra.diasSemContato ?? regra.dias_sem_contato) }))
  .filter((regra) => Number.isFinite(regra.dias) && regra.dias > 0);
if (regras.length === 0) return [];

const menorPrazo = Math.min(...regras.map((regra) => regra.dias));
const janela = { tipo: 'SIMPLES', campo: 'semRetornoDias', operador: 'MAIOR_QUE', valor: String(menorPrazo) };
let criterio = janela;

if (configuracao.modo_teste === true) {
  const telefone = String(configuracao.telefone_teste ?? '').replace(/\D/g, '');
  if (!telefone) return [];
  const telefoneLocal = telefone.startsWith('55') ? telefone.slice(2) : telefone;
  criterio = {
    tipo: 'COMPOSTO', conector: 'E', criterios: [
      janela,
      { tipo: 'SIMPLES', campo: 'telefone', operador: 'CONTEM', valor: telefoneLocal },
    ],
  };
}

return [{ json: { filtro: { criterio, pagina: 0, tamanho: 200 }, menorPrazo } }];
